const payload = $('Execute Workflow Trigger').item.json || {};
const msg = payload.message || payload.body?.message || payload;
const rawText = String(msg?.text || payload.text || '').trim();
const chatId = msg?.chat?.id || payload.chatId || '';
const calendarId = payload.calendarId || 'primary';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}

const text = normalize(rawText);
let action = 'help';

if (/\b(xoa lich|huy lich|delete event|cancel event)\b/.test(text)) {
  action = 'delete_event';
} else if (/\b(kiem tra lich ranh|check lich ranh|co ranh|freebusy|availability|ranh luc)\b/.test(text)) {
  action = 'check_availability';
} else if (/\b(tao lich|dat lich|them lich|tao su kien|dat su kien|book lich|create event)\b/.test(text)) {
  action = 'create_event';
} else if (/\b(lich ngay mai|ngay mai toi co gi|mai toi co gi|list tomorrow|tomorrow schedule)\b/.test(text)) {
  action = 'list_tomorrow';
} else if (/\b(lich hom nay|hom nay toi co gi|xem lich hom nay|today schedule|list today)\b/.test(text)) {
  action = 'list_today';
} else if (/\b(lich|su kien|meeting|hop|calendar|tuan sau|cuoi tuan nay|thu [2-7]|chu nhat)\b/.test(text)) {
  action = 'find_event';
}

return [{ json: { chatId, rawText, text, action, calendarId } }];

const source = $('Chuẩn Bị Calendar').item.json;
const raw = source.rawText;
const text = source.text;
const tzOffset = '+07:00';
const now = new Date();

function pad(n) { return String(n).padStart(2, '0'); }
function buildIso(date, hour, minute) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(hour)}:${pad(minute)}:00${tzOffset}`;
}
function startOfDay(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}
function addDays(base, days) {
  const d = new Date(base);
  d.setDate(d.getDate() + days);
  return d;
}
function nextWeekday(base, targetDow, nextWeek = false) {
  const d = startOfDay(base);
  const currentDow = d.getDay();
  let diff = (targetDow - currentDow + 7) % 7;
  if (diff === 0) diff = 7;
  if (nextWeek) diff += 7;
  d.setDate(d.getDate() + diff);
  return d;
}
function parseTargetDate(text, base) {
  if (/cuoi tuan sau/.test(text)) {
    return startOfDay(nextWeekday(base, 6, true));
  }
  if (/cuoi tuan nay/.test(text)) {
    return startOfDay(nextWeekday(base, 6, false));
  }
  const weekdayMatch = text.match(/thu\s*(2|3|4|5|6|7)|chu nhat/);
  if (weekdayMatch) {
    let targetDow = 0;
    if (weekdayMatch[1]) targetDow = Number(weekdayMatch[1]) - 1;
    const nextWeek = /tuan sau/.test(text);
    return startOfDay(nextWeekday(base, targetDow, nextWeek));
  }
  if (/ngay kia|mot ngay nua/.test(text)) return startOfDay(addDays(base, 2));
  if (/ngay mai|mai/.test(text)) return startOfDay(addDays(base, 1));
  return startOfDay(base);
}
function parseTimeInfo(raw, text) {
  let startHour = null;
  let startMinute = 0;
  let endHour = null;
  let endMinute = 0;
  const rangeMatch = raw.match(/(\d{1,2})(?:[:hg](\d{1,2}))?\s*(?:-|den|toi)\s*(\d{1,2})(?:[:hg](\d{1,2}))?/i);
  const startMatch = raw.match(/(?:luc|vao|tu)?\s*(\d{1,2})(?:[:hg](\d{1,2}))?\s*(am|pm)?/i);
  if (rangeMatch) {
    startHour = Number(rangeMatch[1]);
    startMinute = Number(rangeMatch[2] || 0);
    endHour = Number(rangeMatch[3]);
    endMinute = Number(rangeMatch[4] || 0);
  } else if (startMatch) {
    startHour = Number(startMatch[1]);
    startMinute = Number(startMatch[2] || 0);
    if (startMatch[3] === 'pm' && startHour < 12) startHour += 12;
  } else if (/buoi sang|sang/.test(text)) {
    startHour = 9;
  } else if (/buoi chieu|chieu/.test(text)) {
    startHour = 14;
  } else if (/buoi toi|toi/.test(text)) {
    startHour = 19;
  } else if (/trua/.test(text)) {
    startHour = 12;
  }
  if (startHour !== null && /\b(chieu|toi)\b/.test(text) && startHour < 12) startHour += 12;
  if (endHour !== null && /\b(chieu|toi)\b/.test(text) && endHour < 12) endHour += 12;
  let durationMinutes = 60;
  const durationMatch = text.match(/(\d+)\s*(tieng|gio|h|phut)/);
  if (durationMatch) {
    durationMinutes = Number(durationMatch[1]) * (/phut/.test(durationMatch[2]) ? 1 : 60);
  } else if (/nua tieng|30 phut/.test(text)) {
    durationMinutes = 30;
  } else if (/2 tieng/.test(text)) {
    durationMinutes = 120;
  }
  return { startHour, startMinute, endHour, endMinute, durationMinutes };
}

const targetDate = parseTargetDate(text, now);
const timeInfo = parseTimeInfo(raw, text);
let { startHour, startMinute, endHour, endMinute, durationMinutes } = timeInfo;

if (startHour !== null && endHour === null) {
  const startDate = new Date(buildIso(targetDate, startHour, startMinute));
  const endDate = new Date(startDate.getTime() + durationMinutes * 60000);
  endHour = endDate.getHours();
  endMinute = endDate.getMinutes();
}

let summary = raw
  .replace(/^(tao lich|dat lich|them lich|tao su kien|dat su kien|book lich|create event)\s*/i, '')
  .replace(/\b(luc|vao|tu|den|toi|hom nay|ngay mai|mai|ngay kia|tuan sau|tuan nay|cuoi tuan nay|cuoi tuan sau|chieu|toi|sang|trua|thu\s*[2-7]|chu nhat)\b.*$/i, '')
  .replace(/\d{1,2}(?:[:hg]\d{1,2})?(?:\s*(?:-|den|toi)\s*\d{1,2}(?:[:hg]\d{1,2})?)?/g, '')
  .replace(/\b(trong|khoang|keo dai)\s*\d+\s*(phut|gio|tieng|h)\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();
if (!summary) summary = 'Lịch mới';

const isReady = startHour !== null && endHour !== null;
const start = isReady ? buildIso(targetDate, startHour, startMinute) : '';
const end = isReady ? buildIso(targetDate, endHour, endMinute) : '';
const guidance = '📅 <b>Tạo lịch</b>\n\nBạn hãy nhập theo mẫu như:\n- tạo lịch họp team lúc 15h mai\n- đặt lịch gặp khách 9:30-10:30 thứ 2 tuần sau\n- thêm lịch demo sản phẩm chiều mai 2 tiếng\n- tạo sự kiện cuối tuần này lúc 9h';

return [{
  json: {
    ...source,
    summary,
    start,
    end,
    description: raw,
    location: '',
    isReady,
    response: isReady ? '' : guidance
  }
}];

