}
const date = parseTargetDate(text, now);
const rangeMatch = raw.match(/(\d{1,2})(?:[:hg](\d{1,2}))?\s*(?:-|den|toi)\s*(\d{1,2})(?:[:hg](\d{1,2}))?/i);
const startMatch = raw.match(/(?:luc|vao|tu)?\s*(\d{1,2})(?:[:hg](\d{1,2}))?/i);
let start = '';
